-- Schema snapshot; runtime migration authority: web/store.mjs
PRAGMA foreign_keys=ON;
CREATE TABLE attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,start INTEGER NOT NULL,blocked INTEGER NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,event TEXT REFERENCES events(id),action TEXT NOT NULL,target TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE events(id TEXT PRIMARY KEY,owner TEXT REFERENCES users(id),state TEXT NOT NULL,round TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE failures(key TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE holds(id TEXT PRIMARY KEY,user TEXT REFERENCES users(id),event TEXT REFERENCES events(id),seats TEXT NOT NULL,expires INTEGER NOT NULL,status TEXT NOT NULL,price TEXT NOT NULL, round TEXT NOT NULL DEFAULT 'general', checkout TEXT);
CREATE TABLE mail_outbox(id TEXT PRIMARY KEY,user TEXT REFERENCES users(id),order_id TEXT UNIQUE REFERENCES orders(id),recipient TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE member_grants(user TEXT REFERENCES users(id),event TEXT REFERENCES events(id),expires INTEGER NOT NULL,PRIMARY KEY(user,event));
CREATE TABLE memberships(number TEXT PRIMARY KEY,user TEXT UNIQUE REFERENCES users(id),status TEXT NOT NULL,valid_until INTEGER NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY,user TEXT REFERENCES users(id),message TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE orders(id TEXT PRIMARY KEY,user TEXT REFERENCES users(id),hold TEXT UNIQUE REFERENCES holds(id),created INTEGER NOT NULL);
CREATE TABLE payments(id TEXT PRIMARY KEY,hold TEXT REFERENCES holds(id),status TEXT NOT NULL,amount INTEGER NOT NULL,paid_at INTEGER,refund_amount INTEGER NOT NULL DEFAULT 0, method TEXT NOT NULL DEFAULT 'qr');
CREATE TABLE queues(seq INTEGER PRIMARY KEY AUTOINCREMENT,event TEXT REFERENCES events(id),user TEXT REFERENCES users(id),status TEXT NOT NULL,expires INTEGER NOT NULL, round TEXT NOT NULL DEFAULT 'general',UNIQUE(event,user));
CREATE TABLE refunds(id TEXT PRIMARY KEY,ticket TEXT UNIQUE REFERENCES tickets(id),amount INTEGER NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE sale_rounds(event TEXT REFERENCES events(id),kind TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,PRIMARY KEY(event,kind),CHECK(start<end));
CREATE TABLE seats(event TEXT REFERENCES events(id),id TEXT NOT NULL,zone TEXT NOT NULL,price INTEGER NOT NULL,hold TEXT REFERENCES holds(id),sold INTEGER NOT NULL DEFAULT 0,blocked INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(event,id));
CREATE TABLE sessions(token TEXT PRIMARY KEY,user TEXT REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE tickets(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),event TEXT REFERENCES events(id),seat TEXT NOT NULL,code TEXT UNIQUE NOT NULL,status TEXT NOT NULL,net INTEGER NOT NULL,fee INTEGER NOT NULL,vat INTEGER NOT NULL, holder TEXT);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,presale INTEGER NOT NULL DEFAULT 0, username TEXT);
CREATE UNIQUE INDEX users_username_unique ON users(username);